//! Proposals whose branch fell behind `main` (`SDD.md` §3.2, "Stale proposals").
//!
//! Every proposal rewrites its tenant's kustomize index, so two proposals opened from the same
//! `main` usually conflict there once the first one merges (the forge then refuses the second:
//! Forgejo/Gitea answer "Please try again later" forever). The index is generated by Keel, so on
//! merge Keel rebuilds such a branch on the current `main`: it merges `main` into the reviewed
//! head, re-applies the proposal's index additions/removals to `main`'s index
//! ([`keel_core::merge_kustomization_index`]), commits the result as a single commit on top of
//! `main` (merge-friendly for every forge, fast-forward for the Local Git provider; the original
//! author is kept, the merging user is the committer) and replaces the branch with a lease on
//! the reviewed head. Because the head changed, the merge stops there: the preview is re-run at
//! the new head and the caller gets a `409` asking for a new review (preview-before-merge,
//! `NFR-REL-02`); the merge of the rebuilt head is refused until that preview has finished
//! ([`crate::preview_lifecycle::rebuilt_head_preview_pending`]). Only Keel's own proposal
//! branches (`keel/<tenant>/...`) are rewritten. A conflict in any other file is user content
//! Keel cannot reconcile; it is reported with the files and the way out.

use keel_git::{PullRequestInfo, parse_proposal_branch_tenant};

use crate::auth::AuthSession;
use crate::error::ServerError;
use crate::proposal_repo::{ScopeRepo, WORKTREE_BRANCH};
use crate::state::AppState;

use super::pr::audit_proposal_event;

/// How a PR head relates to its target branch.
#[derive(Debug, Clone, PartialEq, Eq)]
pub(super) enum BranchFreshness {
    /// The head contains the target branch (or the relation could not be determined).
    Current,
    /// The target moved on, but merging it into the head is conflict-free.
    BehindClean,
    /// Merging the target into the head conflicts in these paths.
    Conflicts(Vec<String>),
}

/// Compares the reviewed `head_sha` with the fetched `origin/<target>` of `repo`'s working tree
/// (callers hold [`ScopeRepo::lock`] and refreshed it). Git failures (an old `git` without
/// `merge-tree --write-tree`, missing objects) report [`BranchFreshness::Current`]: the forge
/// then decides as before.
pub(super) async fn branch_freshness(
    state: &AppState,
    repo: &ScopeRepo,
    pr: &PullRequestInfo,
    head_sha: &str,
) -> BranchFreshness {
    let git = &state.git_runner;
    let target = format!("origin/{}", pr.target_branch);
    match git.is_ancestor(&repo.workdir, &target, head_sha).await {
        Ok(true) => return BranchFreshness::Current,
        Ok(false) => {}
        Err(err) => {
            tracing::debug!(pr_id = %pr.id, error = %err, "cannot compare the PR head with its target");
            return BranchFreshness::Current;
        }
    }
    match git.merge_conflicts(&repo.workdir, head_sha, &target).await {
        Ok(paths) if paths.is_empty() => BranchFreshness::BehindClean,
        Ok(paths) => BranchFreshness::Conflicts(paths),
        Err(err) => {
            tracing::debug!(pr_id = %pr.id, error = %err, "cannot test-merge the PR head with its target");
            BranchFreshness::Current
        }
    }
}

/// The Keel-generated index Keel may re-merge in `repo`: the tenant repository's
/// `tenants/<id>/kustomization.yaml`, else the platform repository's `tenants/kustomization.yaml`.
fn managed_index_path(repo: &ScopeRepo) -> String {
    match repo.tenant().filter(|_| repo.is_dedicated()) {
        Some(tenant) => format!("tenants/{tenant}/kustomization.yaml"),
        None => "tenants/kustomization.yaml".to_string(),
    }
}

/// Serializes a merged index exactly like the proposal writers do (a tenant repository index is
/// validated: contained, tenant-relative entries only).
fn serialize_index(repo: &ScopeRepo, entries: &[String]) -> Result<String, ServerError> {
    match repo.tenant().filter(|_| repo.is_dedicated()) {
        Some(tenant) => Ok(keel_kube::build_tenant_repo_kustomization_yaml(
            tenant, entries,
        )?),
        None => crate::routes::serialize_tenants_kustomization(entries),
    }
}

/// `409` for a PR conflicting with `main` outside Keel's generated index.
pub(super) fn user_content_conflict(pr: &PullRequestInfo, paths: &[String]) -> ServerError {
    ServerError::Conflict(format!(
        "PR #{} cannot be merged: changes merged into '{}' after it was opened conflict with it in {}. \
         Keel only reconciles its generated kustomization index automatically. Close this proposal \
         and propose the change again from the current '{}' (re-run the install, edit or delete).",
        pr.id,
        pr.target_branch,
        paths
            .iter()
            .map(|p| format!("'{p}'"))
            .collect::<Vec<_>>()
            .join(", "),
        pr.target_branch,
    ))
}

/// `true` for a branch Keel opened for a proposal in `repo` (`keel/<tenant>/...`; in a tenant
/// repository only that tenant's): the only branches Keel rewrites.
fn is_keel_proposal_branch(repo: &ScopeRepo, branch: &str) -> bool {
    match (
        parse_proposal_branch_tenant(branch),
        repo.tenant().filter(|_| repo.is_dedicated()),
    ) {
        (None, _) => false,
        (Some(owner), Some(tenant)) => owner == tenant,
        (Some(_), None) => true,
    }
}

/// `409` for a stale PR whose branch Keel did not open: Keel never rewrites someone else's
/// branch (history, authorship), so the user brings it up to date.
fn foreign_branch_conflict(pr: &PullRequestInfo, reason: &str) -> ServerError {
    ServerError::Conflict(format!(
        "PR #{} {reason}. Its branch '{}' was not opened by Keel, so Keel does not rewrite it: \
         merge or rebase '{}' into the branch yourself, then merge again.",
        pr.id, pr.source_branch, pr.target_branch,
    ))
}

/// Rebuilds the branch of `pr` (reviewed head `head_sha`) on the current target branch and
/// re-runs its preview. Always returns the error the merge route answers with: a `409` asking
/// for a review of the new preview on success, the user-content conflict, or the failure.
pub(super) async fn rebuild_stale_proposal(
    state: &AppState,
    repo: &ScopeRepo,
    auth: &AuthSession,
    pr: &PullRequestInfo,
    head_sha: &str,
    reason: &str,
) -> ServerError {
    if !is_keel_proposal_branch(repo, &pr.source_branch) {
        return foreign_branch_conflict(pr, reason);
    }
    let new_head = {
        let _guard = repo.lock(state).await;
        match rebuild_locked(state, repo, auth, pr, head_sha).await {
            Ok(sha) => sha,
            Err(err) => return err,
        }
    };
    state.proposal_cache.invalidate(&repo.repository().label);
    super::preview::forget_read_fetches(&repo.workdir);
    if let Some(tenant) = repo.tenant().filter(|_| repo.is_dedicated()) {
        state.tenant_repos.mark_stale(tenant);
    }
    let mut rebuilt = pr.clone();
    rebuilt.head_sha = new_head.clone();
    audit_proposal_event("rebuild", auth, repo, &rebuilt);

    let preview = match repo.preview_key(&pr.id) {
        Ok(key) => crate::preview_lifecycle::rerun_preview_at_commit(state, &key, &new_head).await,
        Err(_) => None,
    };
    let next = match preview {
        Some(run) if run.phase == keel_pko::PreviewPhase::Pending => {
            "A new PKO preview is running for the updated branch; merging is refused until it \
             completes. Review it, then merge again."
                .to_string()
        }
        Some(run) => format!(
            "Re-running the PKO preview failed ({}); review the updated diff before merging again.",
            run.message.unwrap_or_default()
        ),
        None => "Review the updated diff, then merge again.".to_string(),
    };
    ServerError::Conflict(format!(
        "PR #{} {reason}. Keel rebuilt branch '{}' on the current '{}' (new head {}), so the reviewed \
         preview no longer matches what would be merged. {next}",
        pr.id,
        pr.source_branch,
        pr.target_branch,
        &new_head[..new_head.len().min(12)],
    ))
}

/// The rebuild itself (callers hold [`ScopeRepo::lock`]): the new head pushed to the PR branch.
async fn rebuild_locked(
    state: &AppState,
    repo: &ScopeRepo,
    auth: &AuthSession,
    pr: &PullRequestInfo,
    head_sha: &str,
) -> Result<String, ServerError> {
    let git = &state.git_runner;
    let workdir = repo.workdir.as_path();
    if !repo.refresh(state).await? {
        return Err(ServerError::ServiceUnavailable(format!(
            "PR #{} is behind '{}' and no working tree is available to update it",
            pr.id, pr.target_branch
        )));
    }
    let target_sha = git
        .rev_parse(workdir, &format!("origin/{}", pr.target_branch))
        .await?;
    let built = async {
        let conflicted = git
            .start_detached_merge(workdir, head_sha, &target_sha)
            .await?;
        let index_path = managed_index_path(repo);
        let foreign: Vec<String> = conflicted
            .iter()
            .filter(|p| **p != index_path)
            .cloned()
            .collect();
        if !foreign.is_empty() {
            return Err(user_content_conflict(pr, &foreign));
        }
        for path in &conflicted {
            let (base, ours, theirs) = (
                git.read_conflict_stage(workdir, 1, path).await?,
                git.read_conflict_stage(workdir, 2, path).await?,
                git.read_conflict_stage(workdir, 3, path).await?,
            );
            // No base: both sides created the index. A side without it deleted it: user content.
            let merged = match (ours, theirs) {
                (Some(o), Some(t)) => keel_core::merge_kustomization_index(base.as_deref(), &o, &t),
                _ => None,
            }
            .ok_or_else(|| user_content_conflict(pr, std::slice::from_ref(path)))?;
            let yaml = serialize_index(repo, &merged)?;
            crate::routes::write_contained(workdir, &workdir.join(path), yaml).await?;
            git.add(workdir, [path]).await?;
        }
        let tree = git.write_tree(workdir).await?;
        let subject = git
            .commit_subject(workdir, head_sha)
            .await
            .ok()
            .filter(|s| !s.is_empty())
            .unwrap_or_else(|| pr.title.replace(['\r', '\n'], " "));
        let note = format!(
            "Rebuilt by Keel on {} {} (was {}).",
            pr.target_branch,
            &target_sha[..target_sha.len().min(12)],
            &head_sha[..head_sha.len().min(12)],
        );
        // The proposal's author stays the author; the merging user commits the rebuild.
        let committer = crate::routes::commit_author_for_session(auth);
        let author = git
            .commit_author(workdir, head_sha)
            .await
            .ok()
            .filter(|a| a.to_git_author_flag().is_ok())
            .unwrap_or_else(|| committer.clone());
        Ok::<String, ServerError>(
            git.commit_tree(
                workdir,
                &tree,
                &target_sha,
                &[&subject, &note],
                &author,
                &committer,
            )
            .await?,
        )
    }
    .await;
    let _ = git.abort_merge(workdir).await;
    let _ = git
        .reset_branch_to_remote_ref(workdir, "origin", WORKTREE_BRANCH)
        .await;
    let new_head = built?;
    git.push_commit_with_lease(workdir, "origin", &new_head, &pr.source_branch, head_sha)
        .await
        .map_err(|err| {
            tracing::warn!(pr_id = %pr.id, error = %err, "could not replace the stale PR branch");
            ServerError::Conflict(format!(
                "PR #{} is behind '{}', and its branch '{}' changed while Keel was updating it; reload the proposal and merge again",
                pr.id, pr.target_branch, pr.source_branch
            ))
        })?;
    let _ = git.fetch(workdir, "origin").await;
    Ok(new_head)
}
